mapper.select:
select c.*, ct.code as cardTypeCode, ct.name as cardTypeName from card as c left join card_type as ct on c.card_type_id = ct.id


            and c.name like concat("%",#{dto.name}, "%")


            and c.is_limited = #{dto.isLimited}


            and c.status = #{dto.status}


order by c.created_time desc

select c.*, ct.code as cardTypeCode, ct.name as cardTypeName from card as c left join card_type as ct on c.card_type_id = ct.id
where c.id = #{id}
order by c.created_time desc
